const key='fokus-todos-v1';
let tasks=[];let filter='all';
const $=s=>document.querySelector(s);
try{const saved=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(saved))tasks=saved.filter(t=>t&&typeof t.id==='string'&&typeof t.text==='string'&&typeof t.done==='boolean')}catch{$('#notice').textContent='Gespeicherte Aufgaben konnten nicht geladen werden.'}
function save(){try{localStorage.setItem(key,JSON.stringify(tasks));$('#notice').textContent=''}catch{$('#notice').textContent='Speicherung nicht verfügbar. Aufgaben bleiben nur bis zum Schließen dieser Seite erhalten.'}render()}
function render(){const done=tasks.filter(t=>t.done).length;$('#count').textContent=`${tasks.length-done} offen`;$('#clear').disabled=!done;$('#progress').textContent=tasks.length?`${done} von ${tasks.length} erledigt`:'Bereit für deinen ersten Schritt.';const shown=tasks.filter(t=>filter==='all'||(filter==='done'?t.done:!t.done));$('#list').replaceChildren();for(const t of shown){const li=document.createElement('li');li.className=t.done?'done':'';const label=document.createElement('label');const check=document.createElement('input');check.type='checkbox';check.checked=t.done;check.addEventListener('change',()=>{t.done=check.checked;save()});const text=document.createElement('span');text.textContent=t.text;label.append(check,text);const del=document.createElement('button');del.className='delete';del.textContent='×';del.setAttribute('aria-label',`Aufgabe löschen: ${t.text}`);del.onclick=()=>{tasks=tasks.filter(x=>x.id!==t.id);save()};li.append(label,del);$('#list').append(li)}$('#empty').hidden=shown.length>0;$('#empty h3').textContent=tasks.length?(filter==='done'?'Noch nichts abgehakt.':'Alles erledigt. Gut gemacht!'):'Ein freier Kopf beginnt hier.';$('#empty p').textContent=tasks.length?(filter==='done'?'Jeder kleine Schritt zählt.':'Zeit für eine Pause oder deinen nächsten Schritt.'):'Füge deine erste Aufgabe hinzu. Auch kleine Schritte bringen dich weiter.'}
$('#add-form').onsubmit=e=>{e.preventDefault();const text=$('#task-input').value.trim();if(!text)return;tasks.push({id:crypto.randomUUID(),text,done:false});$('#task-input').value='';if(filter==='done')setFilter('all');save();$('#task-input').focus()};
function setFilter(value){filter=value;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)));render()}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>setFilter(b.dataset.filter));$('#clear').onclick=()=>{tasks=tasks.filter(t=>!t.done);save()};render();
